SELECT

FROM RwaInstSpvProductPurchase a WHERE 1 = 1

    AND a.userId = #{userId}


    AND a.instInvestorId = #{instInvestorId}


    AND a.instSpvProductId = #{instSpvProductId}


    AND a.purchaseCurrency = #{purchaseCurrency}


    AND a.purchasePrice = #{purchasePrice}


    AND a.purchaseAmount = #{purchaseAmount}


    AND a.state = #{state}


    AND a.remark = #{remark}


    AND a.createTime = #{createTime}


    AND a.updateBy = #{updateBy}


    AND a.updateTime = #{updateTime}

limit 1

SELECT

FROM RwaInstSpvProductPurchase a WHERE 1 = 1

    AND a.userId = #{userId}


    AND a.instInvestorId = #{instInvestorId}


    AND a.instSpvProductId = #{instSpvProductId}


    AND a.purchaseCurrency LIKE CONCAT('%',#{purchaseCurrency}, '%')


    AND a.purchasePrice = #{purchasePrice}


    AND a.purchaseAmount = #{purchaseAmount}


    AND a.state LIKE CONCAT('%',#{state}, '%')


    AND a.remark LIKE CONCAT('%',#{remark}, '%')


    AND a.createTime = #{createTime}


    AND a.updateBy LIKE CONCAT('%',#{updateBy}, '%')


    AND a.updateTime = #{updateTime}

order by a.createTime desc

SELECT

FROM RwaInstSpvProductPurchase a
INNER JOIN RwaInstSpvProduct b ON a.instSpvProductId = b.id
WHERE b.userId = #{raiseUserId}


    AND a.userId = #{query.userId}


    AND a.instInvestorId = #{query.instInvestorId}


    AND a.instSpvProductId = #{query.instSpvProductId}


    AND a.state LIKE CONCAT('%', #{query.state}, '%')

SELECT
sum(a.purchaseAmount) as totalPurchaseAmount
FROM RwaInstSpvProductPurchase a where 1 = 1

    AND a.userId = #{userId}


    AND a.instSpvProductId = #{instSpvProductId}

SELECT
a.*,
b.tokenName as tokenName
FROM RwaInstSpvProductPurchase a
INNER JOIN RwaInstSpvProduct b ON a.instSpvProductId = b.id
WHERE 1 = 1


    AND a.userId = #{userId}


    AND a.instInvestorId = #{instInvestorId}


    AND a.instSpvProductId = #{instSpvProductId}


    AND a.state LIKE CONCAT('%', #{state}, '%')
